import std.concurrent as conc2
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    io.println("start")
    let a: conc2.Channel<Int64> = conc2.channel(4)
    a.send(1)
    let v = select {
        case x = a.receive() => 1
        case y = a.receive() => 2
    }
    let _ = v
    return Ok(())
}
